  TabPage Tab(string name){TabPage t=new TabPage(name){BackColor=Paper};tabs.TabPages.Add(t);return t;}
  static void AddText(FlowLayoutPanel f,string text,int size,bool bold,int height=32){f.Controls.Add(new Label{Text=text,Width=238,Height=height,Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular),Padding=new Padding(0,6,0,0)});}
  static Button Button(FlowLayoutPanel f,string text,Action a,bool primary){Button b=new Button{Text=text,Width=238,Height=37,FlatStyle=FlatStyle.Flat,BackColor=primary?Blue:Color.White,ForeColor=primary?Color.White:Ink,Margin=new Padding(0,4,0,4)};b.FlatAppearance.BorderColor=Color.FromArgb(210,220,230);b.Click+=(s,e)=>{try{a();}catch(Exception x){MessageBox.Show(x.Message,"Evan's Engines",MessageBoxButtons.OK,MessageBoxIcon.Information);}};f.Controls.Add(b);return b;}
  static NumericUpDown Number(FlowLayoutPanel f,string label,decimal min,decimal max,decimal value,int decimals){AddText(f,label,9,false,25);NumericUpDown n=new NumericUpDown{Minimum=min,Maximum=max,Value=value,DecimalPlaces=decimals,Width=238,Height=30};f.Controls.Add(n);return n;}
  static Chart NewChart(string x,string y){Chart c=new Chart{Dock=DockStyle.Fill,BackColor=Color.White,MinimumSize=new Size(80,80)};ChartArea a=new ChartArea("Plot");a.AxisX.Title=x;a.AxisY.Title=y;a.AxisX.MajorGrid.LineColor=Color.FromArgb(232,238,244);a.AxisY.MajorGrid.LineColor=Color.FromArgb(232,238,244);a.AxisX.LabelStyle.Font=new Font("Segoe UI",8);a.AxisY.LabelStyle.Font=new Font("Segoe UI",8);c.ChartAreas.Add(a);c.Legends.Add(new Legend{Docking=Docking.Bottom,Font=new Font("Segoe UI",9)});return c;}
  static DataGridView Grid(){DataGridView g=new DataGridView{Dock=DockStyle.Fill,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect};g.EnableHeadersVisualStyles=false;g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(225,235,247);g.ColumnHeadersHeight=36;g.RowTemplate.Height=28;g.AlternatingRowsDefaultCellStyle.BackColor=Paper;return g;}
  static Series Line(Chart c,string name,Color color,bool right=false){Series s=new Series(name){ChartType=SeriesChartType.Line,BorderWidth=3,Color=color,YAxisType=right?AxisType.Secondary:AxisType.Primary};c.Series.Add(s);return s;}
  public void RefreshPoint(){if(updating)return;try{point=Model.Calculate(input,(double)rpm.Value,(double)throttle.Value/100,turbo.Checked,sc.Checked);metrics.Text=String.Format(CultureInfo.InvariantCulture,"{0:N0} hp      {1:N0} N m      {2:N0} RPM\n{3}   |   {4:F3} L   |   ESTIMATE",point.HP,point.TorqueNm,point.RPM,point.Mode,point.DisplacementL);metrics.Font=new Font("Segoe UI",14,FontStyle.Bold);
   energy.Text=String.Format(CultureInfo.InvariantCulture,"Air {0:F3} kg/s  |  Manifold {1:F1} kPa absolute  |  Charge {2:F1} C  |  Mean piston speed {3:F2} m/s\nPower balance (kW): indicated {4:F1} - friction {5:F1} - pumping {6:F1} - blower {7:F1} - accessories {8:F1} = brake {9:F1}\nFast model: assumed VE and efficiency. Turbo compressor demand {10:F1} kW; exhaust supply is not solved.",point.AirKgS,point.ManifoldKPa,point.ChargeC,point.MeanPistonMS,point.IndicatedKW,point.FrictionKW,point.PumpingKW,point.SuperchargerDriveKW,point.AccessoryKW,point.BrakeKW,point.TurboCompressorKW);
   if(gearTable!=null)RefreshGears();if(mechanism!=null)mechanism.Invalidate();status.Text="Local app  |  "+input.Cylinders+" cylinders  |  Calculated scenarios; no measured calibration loaded.";
  }catch(Exception e){status.Text=e.Message;}}
  public void RunSweep(bool compare){if(updating||plot==null||inputGrid==null)return;results=new List<Point>();plot.Series.Clear();Color[] colors={Blue,Color.FromArgb(25,145,135),Orange,Color.FromArgb(141,81,177)};for(int mode=0;mode<(compare?4:1);mode++){bool t=compare?(mode&1)!=0:turbo.Checked,s=compare?(mode&2)!=0:sc.Checked;List<Point> run=Model.Sweep(input,(double)throttle.Value/100,t,s);results.AddRange(run);Series power=Line(plot,run[0].Mode+" hp",colors[mode]);foreach(Point p in run)power.Points.AddXY(p.RPM,p.HP);if(!compare){Series torque=Line(plot,"Torque N m",Orange,true);foreach(Point p in run)torque.Points.AddXY(p.RPM,p.TorqueNm);}}
   Point peak=results.OrderByDescending(p=>p.HP).First();plot.Titles.Clear();plot.Titles.Add(new Title(String.Format(CultureInfo.InvariantCulture,"Peak in this sweep: {0:F1} hp @ {1:0} RPM\n{2} | {3:0}% throttle | estimate, 200 RPM steps",peak.HP,peak.RPM,peak.Mode,throttle.Value),Docking.Top,new Font("Segoe UI",10,FontStyle.Bold),Blue));
   plot.ChartAreas[0].AxisY2.Enabled=compare?AxisEnabled.False:AxisEnabled.True;plot.ChartAreas[0].AxisX.Minimum=800;plot.ChartAreas[0].AxisX.Maximum=7000;ShowRows();status.Text="Completed "+results.Count+" steady operating points. Charts and Results contain estimates.";
  }
  void BuildInputs(){TabPage page=Tab("Model inputs");inputGrid=Grid();inputGrid.SelectionMode=DataGridViewSelectionMode.CellSelect;inputGrid.Columns.Add("name","Parameter");inputGrid.Columns.Add("value","Value");inputGrid.Columns.Add("unit","Unit");inputGrid.Columns.Add("source","Source / meaning");inputGrid.Columns[0].ReadOnly=true;inputGrid.Columns[2].ReadOnly=true;inputGrid.Columns[3].ReadOnly=true;inputGrid.Columns[3].FillWeight=180;
   FlowLayoutPanel bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=65,Padding=new Padding(8)};Button(bar,"Apply all input changes",ApplyInputs,true);page.Controls.Add(inputGrid);page.Controls.Add(bar);}
  static readonly string[,] Fields={
   {"Cylinders","Cylinder count","count","CAD default; editable scenario"},{"BoreMm","Bore","mm","CAD default"},{"StrokeMm","Stroke","mm","CAD default"},{"RodMm","Connecting rod length","mm","CAD default"},
   {"CompressionRatio","Compression ratio",":1","Assumed; chamber not measured"},{"AmbientKPa","Ambient pressure","kPa absolute","Assumed condition"},{"AmbientC","Ambient temperature","C","Assumed condition"},{"AFR","Fuel air/fuel mass ratio",":1","Assumed; gasoline surrogate"},{"StoichAFR","Stoichiometric air/fuel ratio",":1","Assumed gasoline"},{"LHV_MJkg","Fuel lower heating value","MJ/kg","Assumed gasoline"},
   {"Gamma","Specific-heat ratio (fast model)","ratio","Assumed; cycle solver uses variable properties"},{"OttoRealization","Ideal-cycle realization (fast model)","fraction","Assumed loss multiplier, uncalibrated"},{"CombustionEfficiency","Released fuel-energy fraction","fraction","Assumed, oxygen-limited"},{"VeScale","Volumetric-efficiency multiplier","factor","Assumed; adjust using measured airflow"},
   {"FrictionBaseBar","Friction pressure: constant","bar","Assumed"},{"FrictionLinear","Friction pressure: piston speed term","bar/(m/s)","Assumed"},{"FrictionSquare","Friction pressure: squared speed term","bar/(m/s)^2","Assumed"},{"AccessoryKW","Accessory power","kW","Assumed"},
   {"TurboPsi","Twin turbo stage request","psi gauge","Parallel pair; same boost, half flow per turbo"},{"SuperchargerPsi","Supercharger stage request","psi gauge","Separate stage pressure ratio"},{"TurboEfficiency","Turbo compressor efficiency","fraction","Assumed; no compressor map"},{"SuperchargerEfficiency","Blower compressor efficiency","fraction","Assumed; no compressor map"},{"IntercoolerEffectiveness","Cooling after EACH stage","fraction","Assumed; no pressure drop"},{"DriveEfficiency","Blower mechanical-drive efficiency","fraction","Assumed"},{"TurboExhaustLossBar","Extra exhaust loss per pressure-ratio rise","bar","Assumed; turbine power balance not solved"}};
  void FillInputs(){inputGrid.Rows.Clear();for(int i=0;i<Fields.GetLength(0);i++){FieldInfo f=typeof(Inputs).GetField(Fields[i,0]);int row=inputGrid.Rows.Add(Fields[i,1],Convert.ToString(f.GetValue(input),CultureInfo.InvariantCulture),Fields[i,2],Fields[i,3]);inputGrid.Rows[row].Tag=Fields[i,0];}for(int i=0;i<input.Ve.Length;i++){int row=inputGrid.Rows.Add("VE at "+input.VeRPM[i]+" RPM",input.Ve[i].ToString("G",CultureInfo.InvariantCulture),"fraction","Assumed airflow table; not calculated from CAD cams");inputGrid.Rows[row].Tag="VE:"+i;}}
  void ApplyInputs(){inputGrid.EndEdit();Inputs next=input.Copy();foreach(DataGridViewRow row in inputGrid.Rows){string tag=(string)row.Tag;double value;if(!double.TryParse(Convert.ToString(row.Cells[1].Value),NumberStyles.Float,CultureInfo.InvariantCulture,out value))throw new ArgumentException("Enter a number for "+row.Cells[0].Value);if(tag.StartsWith("VE:"))next.Ve[int.Parse(tag.Substring(3))]=value;else{FieldInfo f=typeof(Inputs).GetField(tag);if(f.FieldType==typeof(int)){if(value!=Math.Truncate(value))throw new ArgumentException("Cylinder count must be a whole number.");f.SetValue(next,(int)value);}else f.SetValue(next,value);}}next.Validate();input=next;cylinder.Maximum=input.Cylinders;FillInputs();RefreshPoint();RunSweep(false);}
  void BuildResults(){TabPage p=Tab("Results");table=Grid();table.ReadOnly=true;foreach(string name in new[]{"Mode","RPM","HP estimate","N m estimate","BMEP bar","Air kg/s","Charge C"})table.Columns.Add(name,name);p.Controls.Add(table);}
  void ShowRows(){if(table==null)return;table.Rows.Clear();foreach(Point p in results)table.Rows.Add(p.Mode,p.RPM,p.HP.ToString("F2"),p.TorqueNm.ToString("F2"),p.BMEPBar.ToString("F2"),p.AirKgS.ToString("F4"),p.ChargeC.ToString("F1"));}
  void SaveCase(){using(SaveFileDialog d=new SaveFileDialog{Filter="Engine case (*.json)|*.json",InitialDirectory=Path.Combine(Root,"Runs"),FileName="Engine_case_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".json"})if(d.ShowDialog()==DialogResult.OK){CaseFile c=new CaseFile{Inputs=input.Copy(),RPM=(double)rpm.Value,Throttle=(double)throttle.Value/100,Turbo=turbo.Checked,Supercharger=sc.Checked};File.WriteAllText(d.FileName,Inputs.Json.Serialize(c));status.Text="Saved engine case: "+Path.GetFileName(d.FileName);}}
  void LoadCase(){using(OpenFileDialog d=new OpenFileDialog{Filter="Engine case (*.json)|*.json",InitialDirectory=Path.Combine(Root,"Runs")})if(d.ShowDialog()==DialogResult.OK){CaseFile c=Inputs.Json.Deserialize<CaseFile>(File.ReadAllText(d.FileName));c.Inputs.Validate();Inputs.Range(c.RPM,0,7000,"RPM");Inputs.Range(c.Throttle,0,1,"Throttle");updating=true;try{input=c.Inputs;rpm.Value=(decimal)c.RPM;throttle.Value=(decimal)(100*c.Throttle);turbo.Checked=c.Turbo;sc.Checked=c.Supercharger;}finally{updating=false;}cylinder.Maximum=input.Cylinders;FillInputs();RefreshPoint();RunSweep(false);}}
  void Export(){if(results==null||results.Count==0)RunSweep(false);using(SaveFileDialog d=new SaveFileDialog{Filter="CSV results (*.csv)|*.csv",InitialDirectory=Path.Combine(Root,"Runs"),FileName="Engine_sweep_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".csv"})if(d.ShowDialog()==DialogResult.OK){File.WriteAllText(d.FileName,Model.CSV(results));File.WriteAllText(d.FileName+".inputs.json",Inputs.Json.Serialize(new{Inputs=input,RecordedUTC=DateTime.UtcNow.ToString("o"),Throttle=(double)throttle.Value/100,Rows=results.Count,Model="Steady-state mean-value scenario 1.0; not measured power"}));status.Text="Exported CSV and input snapshot.";}}
  void BuildParts(){TabPage p=Tab("Parts & timing");FlowLayoutPanel controls=new FlowLayoutPanel{Dock=DockStyle.Left,Width=255,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(8)};p.Controls.Add(controls);
   cylinder=Number(controls,"Inspect cylinder",1,10,1,0);advanceI=Number(controls,"Intake advance (crank degrees)",-10,10,0,0);advanceE=Number(controls,"Exhaust advance (crank degrees)",-10,10,0,0);
