   ComboBox part=new ComboBox{Width=238,DropDownStyle=ComboBoxStyle.DropDownList};part.Items.AddRange(new object[]{"Piston_4032T6.SLDPRT","Connecting_Rod_4340.SLDPRT","Crankshaft_4340.SLDPRT","Gasket_Head_Left.SLDPRT","Cam_Left_Intake.SLDPRT"});part.SelectedIndex=0;part.SelectedIndexChanged+=(s,e)=>selectedPart=part.Text;controls.Controls.Add(part);Button(controls,"Open native CAD part",()=>OpenCAD(selectedPart),false);
   AddText(controls,"Timing changes animate valve motion. They do not alter the fast model's assumed VE.",9,false,65);
   Panel drawing=new Panel{Dock=DockStyle.Fill};p.Controls.Add(drawing);drawing.BringToFront();mechanism=new SmoothPanel{Dock=DockStyle.Fill,BackColor=Color.White};angle=new TrackBar{Dock=DockStyle.Bottom,Minimum=0,Maximum=720,TickFrequency=90,Height=55};partsText=new Label{Dock=DockStyle.Bottom,Height=72,Padding=new Padding(10)};drawing.Controls.Add(mechanism);drawing.Controls.Add(partsText);drawing.Controls.Add(angle);mechanism.Paint+=DrawMechanism;angle.ValueChanged+=(s,e)=>mechanism.Invalidate();
