  void DrawMechanism(object sender,PaintEventArgs e){if(input==null)return;Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;double phase=Model.Phase((int)cylinder.Value,input),cycle=Model.Mod(angle.Value-phase,720),il=CamProfile.ValveLift(cycle,true,(double)advanceI.Value),el=CamProfile.ValveLift(cycle,false,(double)advanceE.Value);float scale=Math.Min((mechanism.ClientSize.Height-115)/360f,(mechanism.ClientSize.Width-60)/230f);if(scale<.2)return;float center=mechanism.ClientSize.Width/2f,top=60;
   Func<double,double,System.Drawing.PointF> xy=(x,y)=>new System.Drawing.PointF(center+(float)x*scale,top+(float)y*scale);
   double r=input.StrokeMm/2,l=input.RodMm,a=cycle*Math.PI/180,yCrank=75+r+l,px=r*Math.Sin(a),py=yCrank-r*Math.Cos(a),pistonY=py-Math.Sqrt(l*l-px*px);
   using(Pen grey=new Pen(Color.FromArgb(145,162,179),3)){g.DrawRectangle(grey,center-(float)input.BoreMm/2*scale,top+48*scale,(float)input.BoreMm*scale,(float)(input.StrokeMm+52)*scale);}
   using(SolidBrush silver=new SolidBrush(Color.FromArgb(190,203,217)))g.FillRectangle(silver,center-(float)(input.BoreMm/2-2)*scale,top+(float)(pistonY-15)*scale,(float)(input.BoreMm-4)*scale,30*scale);
   using(Pen rod=new Pen(Ink,9*scale))g.DrawLine(rod,xy(0,pistonY),xy(px,py));using(Pen crank=new Pen(Blue,12*scale))g.DrawLine(crank,xy(0,yCrank),xy(px,py));using(Pen ring=new Pen(Color.FromArgb(160,177,194),2))g.DrawEllipse(ring,center-(float)r*scale,top+(float)(yCrank-r)*scale,(float)(2*r)*scale,(float)(2*r)*scale);
   for(int k=0;k<2;k++){float x=center+(k==0?-22:22)*scale,vy=top+(float)(40+(k==0?il:el))*scale;using(Pen valve=new Pen(k==0?Blue:Orange,5*scale)){g.DrawLine(valve,x,vy-30*scale,x,vy);g.DrawLine(valve,x-10*scale,vy,x+10*scale,vy);}using(SolidBrush cam=new SolidBrush(k==0?Blue:Orange))g.FillEllipse(cam,x-10*scale,top-5*scale,20*scale,20*scale);}
   g.DrawString("Cylinder "+cylinder.Value+"   |   720-degree four-stroke cycle",Font,Brushes.DimGray,12,12);
   partsText.Text=String.Format(CultureInfo.InvariantCulture,"Crank {0:F0} deg | Cylinder cycle {1:F0} deg | Piston below TDC {2:F3} mm\nIntake lift {3:F3} mm | Exhaust lift {4:F3} mm | Cam speed = crank / 2\nDiagram shows exact slider-crank geometry; drawing is schematic.",angle.Value,cycle,Model.PistonBelowTDC(cycle,input),il,el);
  }
  void BuildGears(){TabPage p=Tab("Gearbox");gearTable=Grid();gearTable.ReadOnly=true;foreach(string h in new[]{"Gear","Ratio in/out","Output RPM","Output torque N m","Output power kW"})gearTable.Columns.Add(h,h);Label note=new Label{Dock=DockStyle.Bottom,Height=78,Padding=new Padding(10),Text="Ideal gear calculations use the current engine operating point and 95% assumed transmission efficiency.\nNo clutch slip, shift transient, fluid torque converter, temperatures or component strength is solved.\nThe six ratios match your CAD concept; output torque can be negative when engine power is negative."};p.Controls.Add(gearTable);p.Controls.Add(note);}
  void RefreshGears(){gearTable.Rows.Clear();for(int i=0;i<Model.Gears.Length;i++)gearTable.Rows.Add(i+1,Model.Gears[i].ToString("F5"),(point.RPM/Model.Gears[i]).ToString("F1"),(point.TorqueNm*Model.Gears[i]*.95).ToString("F1"),(point.BrakeKW*.95).ToString("F2"));}
  void BuildCycle(){TabPage p=Tab("Cylinder physics");FlowLayoutPanel bar=new FlowLayoutPanel{Dock=DockStyle.Left,Width=255,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(8)};p.Controls.Add(bar);cycleStart=Number(bar,"Heat release starts (deg after firing TDC)",-35,10,-15,0);burnDuration=Number(bar,"Heat release duration (crank deg)",15,120,60,0);wallT=Number(bar,"Assumed wall temperature (K)",280,650,450,0);wallH=Number(bar,"Heat-transfer coefficient (W/m2/K)",0,1000,250,0);
   cycleRun=Button(bar,"Run cylinder physics",()=>{},true);cycleRun.Click+=async(s,e)=>await RunCycle();AddText(bar,"Cantera gas properties + imposed heat release. Closed compression and expansion. No chemical ignition or gas exchange prediction.",9,false,100);
   Panel main=new Panel{Dock=DockStyle.Fill};p.Controls.Add(main);main.BringToFront();cyclePlot=NewChart("Crank degrees after firing TDC","Cylinder pressure (bar absolute)");cycleInfo=new Label{Dock=DockStyle.Bottom,Height=115,Padding=new Padding(10),Text="Run the current operating point. The app checks energy balance and repeats with half the angle step.\nThis solver does not use the fast model's ideal-cycle realization multiplier."};main.Controls.Add(cyclePlot);main.Controls.Add(cycleInfo);
  }
  async Task RunCycle(){if(point.RPM<100){MessageBox.Show("Set RPM to at least 100 for the cylinder calculation.");return;}cycleRun.Enabled=false;cycleInfo.Text="Calculating locally and checking the finer angle step...";try{
   string id=DateTime.UtcNow.ToString("yyyyMMdd_HHmmss_fff"),request=Path.Combine(Root,"Runs","Cycle_"+id+".request.json"),response=Path.Combine(Root,"Runs","Cycle_"+id+".json");
   File.WriteAllText(request,Inputs.Json.Serialize(new{Inputs=input.Copy(),OperatingPoint=point,StartDeg=(double)cycleStart.Value,DurationDeg=(double)burnDuration.Value,WallK=(double)wallT.Value,HeatCoefficient=(double)wallH.Value,OutputPath=response}));
   var cfg=Inputs.Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(Root,"runtime.json")));string python=cfg["Python"];if(!Path.IsPathRooted(python))python=Path.Combine(Root,python);string solver=Path.Combine(Root,"Source","cycle_solver.py");if(!File.Exists(solver))solver=Path.Combine(Root,"cycle_solver.py");
   string result=await Task.Run(()=>{ProcessStartInfo si=new ProcessStartInfo(python,"\""+solver+"\" --request \""+request+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true,WorkingDirectory=Root};using(Process proc=Process.Start(si)){Task<string> stdout=proc.StandardOutput.ReadToEndAsync(),stderr=proc.StandardError.ReadToEndAsync();if(!proc.WaitForExit(60000)){proc.Kill();throw new Exception("Cylinder solve exceeded one minute.");}Task.WaitAll(stdout,stderr);if(proc.ExitCode!=0)throw new Exception(stderr.Result);return File.ReadAllText(response);}});
   var data=Inputs.Json.Deserialize<Dictionary<string,object>>(result);var rows=(System.Collections.IEnumerable)data["trace"];cyclePlot.Series.Clear();Series curve=Line(cyclePlot,"Closed-cylinder scenario",Blue);foreach(object row in rows){var d=(Dictionary<string,object>)row;curve.Points.AddXY(Convert.ToDouble(d["crank_deg"]),Convert.ToDouble(d["pressure_bar"]));}
   cycleInfo.Text=String.Format(CultureInfo.InvariantCulture,"Peak {0:F2} bar | Closed-cycle work {1:F2} J/cylinder | Brake estimate {2:F1} hp\nEnergy residual {3:E2} J | Half-step work change {4:F5}% | Check: {5}\nSaved pressure trace and full request to Runs. Gas exchange, knock, combustion chemistry and turbine matching are not solved.",data["peak_pressure_bar"],data["closed_work_J"],data["brake_hp_estimate"],data["energy_residual_J"],data["work_step_change_pct"],data["numerical_check"]);
   status.Text="Cylinder physics saved: "+Path.GetFileName(response);
  }catch(Exception e){cycleInfo.Text="Calculation failed: "+e.Message;MessageBox.Show(e.Message,"Cylinder calculation");}finally{cycleRun.Enabled=true;}}
  void BuildThermal(){TabPage p=Tab("Thermal");FlowLayoutPanel controls=new FlowLayoutPanel{Dock=DockStyle.Left,Width=255,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(8)};NumericUpDown mass=Number(controls,"Object mass (kg)",.1m,10000,100,1),cp=Number(controls,"Heat capacity (J/kg/K)",100,5000,900,0),ua=Number(controls,"Heat loss (W/K)",1,100000,200,0),heat=Number(controls,"Constant heat input (W)",0,1000000,20000,0),ambient=Number(controls,"Ambient / initial temperature (C)",-20,100,25,0);
   Action run=()=>{thermalPlot.Series.Clear();Series s=Line(thermalPlot,"Uniform-temperature scenario",Blue);double tau=(double)(mass.Value*cp.Value/ua.Value),t0=(double)ambient.Value,ss=t0+(double)(heat.Value/ua.Value);for(int t=0;t<=3600;t+=30)s.Points.AddXY(t,ss+(t0-ss)*Math.Exp(-t/tau));};Button(controls,"Calculate warm-up",run,true);AddText(controls,"Lumped thermal model. One uniform temperature; constant heat input and cooling. Not a predicted engine block temperature.",9,false,100);thermalPlot=NewChart("Elapsed time (s)","Object temperature (C)");p.Controls.Add(thermalPlot);p.Controls.Add(controls);run();}
  void BuildNotes(){TabPage p=Tab("Accuracy & sources");TextBox t=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",11),Text=
   "EVAN'S ENGINES 0.3\r\n\r\nGT-POWER inspired workflow; an independent concept tool. It does not contain GT-POWER code or its solver.\r\n\r\nFast performance: prescribed airflow/VE, ideal-cycle efficiency with an assumed realization factor, oxygen-limited fuel energy, friction/pumping/accessory losses and compressor heating. These are scenarios, not calibrated power predictions.\r\n\r\nCylinder physics: Cantera temperature-dependent air properties; closed compression/expansion, RK4 crank-angle integration, imposed Wiebe heat release and assumed wall heat transfer. Includes energy balance and step convergence. No chemical combustion, valve gas exchange, knock, emissions or turbine balance.\r\n\r\nParts: CAD slider-crank and valve-lift motion. Cam interpolation adapted from MIT-licensed Engine Simulator by Ange Yaghi. Timing controls do not update airflow estimates automatically.\r\n\r\nSOLIDWORKS: native parts open in CAD. Supported API mass/material readback is provided separately. CAD geometry does not determine horsepower.\r\n\r\nGearbox: ideal ratios with assumed 95% efficiency; no automatic shift control or torque-converter fluid model.\r\n\r\nThermal: independent one-temperature heat balance, not a finite element temperature/stress result.\r\n\r\n7000 RPM is the initial calculation range, not a mechanically validated redline. A result inside the range does not establish durability.\r\n\r\nTo improve accuracy: load measured VE/airflow, compression/chamber volumes, fuel properties, cylinder-pressure data, compressor/turbine maps and loss data. Numerical checks prove calculation consistency, not physical validation.\r\n\r\nREA 6.7.0 inspected our existing controller and compiled app. Evidence and original source excerpts are retained locally. REA is an analysis tool, not a physics solver.\r\n\r\nSources and licenses are in README.txt and LICENSES. No internet connection is needed to run the installed app."};p.Controls.Add(t);}
  static void OpenPath(string path){if(!File.Exists(path)&&!Directory.Exists(path))throw new FileNotFoundException("Not found: "+path);Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}
  void ReadCAD(){string helper=Path.Combine(Root,"CadReadback.exe");if(!File.Exists(helper))throw new Exception("The optional SOLIDWORKS helper is not installed. Build it against your licensed SOLIDWORKS API interop library.");using(Process proc=Process.Start(new ProcessStartInfo(helper){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Root})){if(!proc.WaitForExit(15000))throw new Exception("CAD is busy; close dialogs and retry.");if(proc.ExitCode!=0)throw new Exception(File.ReadAllText(Path.Combine(Root,"Evidence","CAD_Readback_Error.txt")));}var data=Inputs.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Root,"Runs","SOLIDWORKS_Readback.json")));MessageBox.Show(String.Format(CultureInfo.InvariantCulture,"{0}\nConfiguration: {1}\nAssigned CAD mass: {2:F3} kg\nVolume: {3:F6} m3\nMaterial: {4}\n\nRead-only CAD properties; no performance or strength validation.",data["document"],data["configuration"],data["mass_kg"],data["volume_m3"],data["material"]),"SOLIDWORKS readback");}
  static void OpenCAD(string file){string folder=Path.GetFullPath(Path.Combine(Root,"..","Ford_427_V10_Development")),path=Path.Combine(folder,file);if(!File.Exists(path)){string[] candidates=Directory.Exists(folder)?Directory.GetFiles(folder,"*"+file.Replace(".SLDPRT","")+"*",SearchOption.AllDirectories):new string[0];if(candidates.Length==1)path=candidates[0];else throw new FileNotFoundException("That native part name was not found. Open the assembly and select the part in SOLIDWORKS.");}OpenPath(path);}
  public void SmokeCheck(){RefreshPoint();RunSweep(true);if(results.Count!=128)throw new Exception("Four-mode sweep failed.");turbo.Checked=true;sc.Checked=true;RefreshPoint();if(point.PressureRatio<=1)throw new Exception("Boost mode failed.");turbo.Checked=false;sc.Checked=false;RunSweep(false);for(int i=0;i<tabs.TabPages.Count;i++){tabs.SelectedIndex=i;Application.DoEvents();using(Bitmap bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(Path.Combine(Root,"Evidence","Tab_"+i+".png"));}}tabs.SelectedIndex=0;Application.DoEvents();}
  public async Task IntegrationCheck(){await RunCycle();if(!cycleInfo.Text.Contains("Check: PASS"))throw new Exception("Cylinder UI integration failed: "+cycleInfo.Text);tabs.SelectedIndex=2;Application.DoEvents();using(Bitmap bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(Path.Combine(Root,"Evidence","Cylinder_UI.png"));}File.WriteAllText(Path.Combine(Root,"Evidence","Cylinder_UI_Check.txt"),"PASS: native app saved request, launched local Cantera backend, read pressure trace and numerical PASS, and plotted result.");}
 }
 public static class Program {
  [STAThread] public static int Main(string[] args){try{if(args.Contains("--self-test"))return Checks.Run();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Directory.CreateDirectory(Path.Combine(Lab.Root,"Runs"));using(Lab app=new Lab()){if(args.Contains("--smoke-test")){app.Show();app.SmokeCheck();using(Bitmap bmp=new Bitmap(app.Width,app.Height)){app.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(Path.Combine(Lab.Root,"Evidence","App_Smoke.png"));}File.WriteAllText(Path.Combine(Lab.Root,"Evidence","UI_Smoke.txt"),"PASS: construction, all tabs, four boost modes, 128 operating points, reset to baseline.");return 0;}if(args.Contains("--cad-test")){app.Show();app.CadPreviewCheck();return 0;}if(args.Contains("--live-test")){app.Show();app.LiveCheck();return 0;}if(args.Contains("--run-live"))app.Shown+=(s,e)=>app.BeginLive();int code=0;if(args.Contains("--integration-test"))app.Shown+=async(s,e)=>{try{await app.IntegrationCheck();}catch(Exception x){File.WriteAllText(Path.Combine(Lab.Root,"Evidence","Integration_Error.txt"),x.ToString());code=1;}app.Close();};Application.Run(app);return code;}}catch(Exception e){File.WriteAllText(Path.Combine(Lab.Root,"Evidence","Last_Error.txt"),e.ToString());if(!args.Contains("--self-test"))MessageBox.Show(e.Message,"Evan's Engines");return 1;}}
 }
